-- Water bodies dataset generated from raw/water-bodies-master.csv
SET NAMES utf8mb4;
DROP TABLE IF EXISTS water_bodies;
CREATE TABLE water_bodies (
  id TEXT NULL,
  slug TEXT NULL,
  name_en TEXT NULL,
  name_bn TEXT NULL,
  alternate_names TEXT NULL,
  hydrological_class TEXT NULL,
  water_body_type TEXT NULL,
  water_body_subtype TEXT NULL,
  district TEXT NULL,
  upazila TEXT NULL,
  latitude DECIMAL(10,6) NULL,
  longitude DECIMAL(10,6) NULL,
  transboundary_flag TEXT NULL,
  transboundary_countries TEXT NULL,
  primary_source TEXT NULL,
  source_urls TEXT NULL,
  source_count INT NULL,
  data_confidence TEXT NULL,
  last_verified_at TEXT NULL,
  notes TEXT NULL
);
